   689  static void
   690  fu_coswid_firmware_write_hash(cbor_item_t *root, FuCoswidFirmwareHash *hash)
   691  {
   692          g_autoptr(cbor_item_t) item_hash = cbor_new_definite_array(2);
   693          g_autoptr(cbor_item_t) item_hash_alg_id = cbor_build_uint8(hash->alg_id);
   694          g_autoptr(cbor_item_t) item_hash_value =
   695              cbor_build_bytestring(hash->value->data, hash->value->len);
   696          if (!cbor_array_push(item_hash, item_hash_alg_id))
   697                  g_critical("failed to push to definite array");
   698          if (!cbor_array_push(item_hash, item_hash_value))
   699                  g_critical("failed to push to definite array");
   700          if (!cbor_array_push(root, item_hash))
   701                  g_critical("failed to push to indefinite array");
   702  }
