   257  /**
   258   * fu_coswid_write_tag_u64:
   259   * @item: a #cbor_item_t
   260   * @tag: a #FuCoswidTag, e.g. %FU_COSWID_TAG_PAYLOAD
   261   * @value: unsigned integer
   262   *
   263   * Writes a #guint64 tag value.
   264   *
   265   * Returns: %TRUE for success
   266   *
   267   * Since: 1.9.17
   268   **/
   269  void
   270  fu_coswid_write_tag_u64(cbor_item_t *item, FuCoswidTag tag, guint64 value)
   271  {
   272          g_autoptr(cbor_item_t) key = cbor_build_uint8(tag);
   273          g_autoptr(cbor_item_t) val = cbor_build_uint64(value);
   274          if (!cbor_map_add(item, (struct cbor_pair){.key = key, .value = val}))
   275                  g_critical("failed to push u64 to indefinite map");
   276  }
